steps.starter:
{{pins}}
const int DARK = 200;

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int light = analogRead(LIGHT_PIN);
  if (light < DARK) {
    digitalWrite(LED_PIN, HIGH);
    // beep
  } else {
    digitalWrite(LED_PIN, LOW);
    // stop beeping
  }
  delay(100);
}

steps.demo:
{{pins}}
const int DARK = 200;

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int light = analogRead(LIGHT_PIN);
  if (light < DARK) {
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 880);
  } else {
    digitalWrite(LED_PIN, LOW);
    noTone(BUZZER_PIN);
  }
  delay(100);
}
